import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ page, signIn }) => {
  // Arrange
  await signIn("member");
  const before = (await page.context().cookies()).find((c) => c.name === "session");
  expect(before?.value, "member is signed in before signing out").toBeTruthy();

  // Act
  const response = await page.request.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const setCookie = response
    .headersArray()
    .filter((h) => h.name.toLowerCase() === "set-cookie")
    .map((h) => h.value)
    .find((v) => v.startsWith("session="));
  expect(setCookie, "logout sends a Set-Cookie for the session cookie").toBeDefined();
  expect(setCookie).toMatch(/max-age=0|expires=thu, 01 jan 1970/i);

  // Re-read the stored outcome: the browser no longer holds a session cookie.
  const after = (await page.context().cookies()).find((c) => c.name === "session");
  expect(after, "session cookie is removed from the browser").toBeUndefined();
});
